{{ config(
            materialized='table',
                post_hook={
                    "sql": "INSERT INTO `zouk-wh.MapleMonk.finance_pricemaster_ccogs_Myntra_History` ( WMS_SKU, BAU, NLC, NLC_wo_tax, snapshot_date, snapshot_timestamp, record_hash ) WITH Current_Master AS ( SELECT UPPER(TRIM(WMS_SKU)) AS WMS_SKU, SAFE_CAST(BAU AS FLOAT64) AS BAU, SAFE_CAST(NLC AS FLOAT64) AS NLC, SAFE_CAST(Cost_Price AS FLOAT64) AS NLC_wo_tax FROM `zouk-wh.MapleMonk.finance_pricemaster_ccogs_Myntra` WHERE WMS_SKU IS NOT NULL ), Hashed_Master AS ( SELECT *, TO_HEX( MD5( CONCAT( COALESCE(WMS_SKU, \'\'), \'|\', COALESCE(CAST(BAU AS STRING), \'\'), \'|\', COALESCE(CAST(NLC AS STRING), \'\'), \'|\', COALESCE(CAST(NLC_wo_tax AS STRING), \'\') ) ) ) AS record_hash FROM Current_Master ), Latest_History AS ( SELECT WMS_SKU, record_hash FROM `zouk-wh.MapleMonk.finance_pricemaster_ccogs_Myntra_History` QUALIFY ROW_NUMBER() OVER ( PARTITION BY WMS_SKU ORDER BY snapshot_date DESC, snapshot_timestamp DESC ) = 1 ) SELECT h.WMS_SKU, h.BAU, h.NLC, h.NLC_wo_tax, CURRENT_DATE(\'Asia/Kolkata\') AS snapshot_date, CURRENT_TIMESTAMP() AS snapshot_timestamp, h.record_hash FROM Hashed_Master h LEFT JOIN Latest_History l ON h.WMS_SKU = l.WMS_SKU WHERE l.WMS_SKU IS NULL OR h.record_hash != l.record_hash; CREATE TABLE IF NOT EXISTS `zouk-wh.MapleMonk.finance_ccogs_myntra` ( channel_name STRING, ccogs_date DATE, ccogs FLOAT64 ); DELETE FROM `zouk-wh.MapleMonk.finance_ccogs_myntra` WHERE ccogs_date BETWEEN DATE \'2026-08-01\' AND CURRENT_DATE(\'Asia/Kolkata\') AND channel_name NOT IN (\'MYNTRA_B2B\', \'MYNTRA_SOR\'); MERGE INTO `zouk-wh.MapleMonk.finance_ccogs_myntra` AS target USING ( WITH Myntra_Sales AS ( SELECT * FROM `zouk-wh.MapleMonk.zouk_secondary_sales_consolidated_MP` WHERE LOWER(marketplace) IN ( \'myntra_b2b\', \'myntra_sor\' ) AND DATE(Order_Date) BETWEEN DATE \'2026-08-01\' AND CURRENT_DATE(\'Asia/Kolkata\') ), Costmaster_History AS ( SELECT UPPER(TRIM(WMS_SKU)) AS WMS_SKU, BAU, NLC, NLC_wo_tax, snapshot_date FROM `zouk-wh.MapleMonk.finance_pricemaster_ccogs_Myntra_History` WHERE NLC IS NOT NULL AND NLC > 0 ), Myntra_Base AS ( SELECT m.SKU_Code AS sku, UPPER(m.marketplace) AS sales_channel, DATE(m.Order_Date) AS Order_Date, COALESCE( SAFE_CAST(s.BAU AS FLOAT64), 0 ) AS BAU, SAFE_CAST( s.NLC AS FLOAT64 ) AS NLC, SAFE_CAST( s.NLC_wo_tax AS FLOAT64 ) AS NLC_wo_tax, 0.14 AS trade_margin_pct, COALESCE( SAFE_CAST( m.QUANTITY AS FLOAT64 ), 0 ) AS QUANTITY, COALESCE( SAFE_CAST( m.SELLING_PRICE AS FLOAT64 ), 0 ) AS SELLING_PRICE, s.snapshot_date AS cost_snapshot_date, SAFE_DIVIDE( SAFE_CAST(m.SELLING_PRICE AS FLOAT64), NULLIF( SAFE_CAST(m.QUANTITY AS FLOAT64), 0 ) ) AS asp_with_tax FROM Myntra_Sales m LEFT JOIN Costmaster_History s ON UPPER(TRIM(m.SKU_Code)) = UPPER(TRIM(s.WMS_SKU)) AND s.snapshot_date <= DATE(m.Order_Date) QUALIFY ROW_NUMBER() OVER ( PARTITION BY m.SKU_Code, m.Order_Date, m.Order_ID ORDER BY s.snapshot_date DESC ) = 1 ), Final_Myntra_CCOGS AS ( SELECT sku, sales_channel, Order_Date, BAU, NLC, NLC_wo_tax, trade_margin_pct, QUANTITY, SELLING_PRICE, cost_snapshot_date, asp_with_tax, SAFE_DIVIDE( asp_with_tax, 1.05 ) AS asp_without_tax, SAFE_DIVIDE( asp_with_tax * (1 - trade_margin_pct), 1.05 ) AS unit_cost_without_tax, NLC_wo_tax - SAFE_DIVIDE( asp_with_tax * (1 - trade_margin_pct), 1.05 ) AS ccogs_per_unit FROM Myntra_Base ), Daily_CCOGS AS ( SELECT sales_channel AS channel_name, Order_Date AS ccogs_date, SUM( ccogs_per_unit * QUANTITY * 0.85 ) AS ccogs FROM Final_Myntra_CCOGS GROUP BY sales_channel, Order_Date ) SELECT channel_name, ccogs_date, ccogs FROM Daily_CCOGS ) AS source ON target.channel_name = source.channel_name AND target.ccogs_date = source.ccogs_date WHEN MATCHED THEN UPDATE SET target.ccogs = source.ccogs WHEN NOT MATCHED THEN INSERT ( channel_name, ccogs_date, ccogs ) VALUES ( source.channel_name, source.ccogs_date, source.ccogs );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            